from fractions import Fraction
from typing import Sequence

def discrete_path_is_continuous(values: Sequence[Fraction]) -> bool:
    return all(left == right for left, right in zip(values, values[1:]))

if __name__ == "__main__":
    stationary = [Fraction(1, 3)] * 10
    moving = [Fraction(n, 9) for n in range(10)]
    print("stationary:", discrete_path_is_continuous(stationary))
    print("moving:", discrete_path_is_continuous(moving))

